"""Demo: random verification that finite-arity powers commute with directed unions.

Draws random finite tuples over {0,...,LIMIT} and confirms both directions of the
set identity  {tuples coord-wise in the union} == {tuples inside a single stage}
by exhibiting the merged stage M = max(tuple).
"""
from __future__ import annotations
from typing import List, Sequence
import random


def lift(tup: Sequence[int]) -> int:
    return max(tup) if tup else 0


def coordinatewise_in_union(tup: Sequence[int], limit: int) -> bool:
    return all(0 <= x <= limit for x in tup)  # union_i {0..i} up to limit


def inside_single_stage(tup: Sequence[int]) -> bool:
    m = lift(tup)
    return all(0 <= x <= m for x in tup)


def main(trials: int = 10000, limit: int = 50) -> None:
    ok = 0
    for _ in range(trials):
        n = random.randint(1, 6)
        tup: List[int] = [random.randint(0, limit) for _ in range(n)]
        # both membership predicates must agree (set identity)
        if coordinatewise_in_union(tup, limit) == inside_single_stage(tup):
            ok += 1
    print(f"finite-arity identity held on {ok}/{trials} random tuples")


if __name__ == "__main__":
    main()

